import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());
        if (n > 40) {
            out.println(0);
            out.flush();
            return;
        }
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            points.add(new Point(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]),
                                 Integer.parseInt(parts[2]), Integer.parseInt(parts[3]),
                                 Integer.parseInt(parts[4])));
        }
        if (n < 3) {
            out.println(n);
            for (int i = 1; i <= n; i++) {
                out.println(i);
            }
            out.flush();
            return;
        }
        List<Integer> result = new ArrayList<>();
        for (int centerIdx = 0; centerIdx < n; centerIdx++) {
            boolean isCenter = true;
            for (int aIdx = 0; aIdx < n; aIdx++) {
                if (aIdx == centerIdx) continue;
                for (int bIdx = 0; bIdx < n; bIdx++) {
                    if (bIdx == centerIdx || bIdx == aIdx) continue;
                    Point A = points.get(aIdx).minus(points.get(centerIdx));
                    Point B = points.get(bIdx).minus(points.get(centerIdx));
                    if (A.dot(B)) {
                        isCenter = false;
                        break;
                    }
                }
                if (!isCenter) break;
            }
            if (isCenter) result.add(centerIdx + 1);
        }
        out.println(result.size());
        for (int id : result) {
            out.println(id);
        }
        out.flush();
    }

    static class Point {
        long a, b, c, d, e;
        Point(long a, long b, long c, long d, long e) {
            this.a = a; this.b = b; this.c = c; this.d = d; this.e = e;
        }
        boolean dot(Point rhs) {
            return a * rhs.a + b * rhs.b + c * rhs.c + d * rhs.d + e * rhs.e > 0;
        }
        Point minus(Point rhs) {
            return new Point(a - rhs.a, b - rhs.b, c - rhs.c, d - rhs.d, e - rhs.e);
        }
    }
}
